  title-wrap small  : "All Snippets"
  editor buffer(draft): "body-of-beta"          <-- still the PREVIOUS fragment
  copy button present: true
  notices raised by copy(): 1 ["Copied fragment"]
  clipboard receives: ["body-of-beta"]          <-- WRONG fragment on the clipboard
