  title input            : Alpha
  editor loaded          : "ORIGINAL BODY\n"
  footer at rest         : "14 chars · 2 wordsLast edited 1m agoSaved"
  Save changes clicked   : Save changes
  typed mid-save, editor : "FIRST-HALF SECOND-HALF"
  footer mid-save        : "22 chars · 2 wordsUnsaved changesSave changes"
  footer after settle    : "22 chars · 2 wordsLast edited 1m agoSaved"
